export function clean(input: string): string {
  // Remove all non-digit characters
  let cleaned = input.replace(/\D/g, '');

  // Remove the country code if present
  if (cleaned.startsWith('1')) {
    cleaned = cleaned.slice(1);
  }

  return cleaned;
}

