  let result = '';
  for (let i = 1; i <= diamondSize; i++) {
      const spaces = ' '.repeat(diamondSize - i);
      const letter = String.fromCharCode(64 + i);
      const innerSpaces = i > 1 ? ' '.repeat(2 * i - 3) : '';
      result += spaces + letter + innerSpaces + (i > 1 ? letter : '') + spaces + '\n';
    }
  for (let i = diamondSize - 1; i >= 1; i--) {
