export function verse(n: number): string {
  const animals = [
    { name: "fly", description: "", swallowed: false },
    { name: "spider", description: "It wriggled and jiggled and tickled inside her.", swallowed: true },
    { name: "bird", description: "How absurd to swallow a bird!", swallowed: true },
    { name: "cat", description: "Imagine that, to swallow a cat!", swallowed: true },
    { name: "dog", description: "What a hog, to swallow a dog!", swallowed: true },
    { name: "goat", description: "Just opened her throat and swallowed a goat!", swallowed: true },
    { name: "cow", description: "I don't know how she swallowed a cow!", swallowed: true },
    { name: "horse", description: "She's dead, of course!", swallowed: false }
  ];

  if (n < 1 || n > animals.length) {
    throw new Error("Invalid verse number");
  }

  let result = `I know an old lady who swallowed a ${animals[n - 1].name}.\n`;

  if (animals[n - 1].name === "horse") {
    result += animals[n - 1].description;
  } else {
    result += animals[n - 1].description + "\n";
    for (let i = n - 1; i > 0; i--) {
      if (animals[i].swallowed) {
        result += `She swallowed the ${animals[i].name} to catch the ${animals[i - 1].name}${i > 1 ? " that wriggled and jiggled and tickled inside her" : ""}.\n`;
      }
    }
    result += "I don't know why she swallowed the fly. Perhaps she'll die.\n";
  }

  return result;
}

export function verses(start: number, end: number): string {
  let result = "";
  for (let i = start; i <= end; i++) {
    result += verse(i) + "\n";
  }
  return result.trim() + "\n";
}

