// @openarc:begin matchingBrackets.isPaired
export const isPaired: IsPairedFn = (input) => {
  const stack: string[] = [];
    const openBrackets = '([{';
    const closeBrackets = ')]}';
    const matchingBrackets: { [key: string]: string } = { '(': ')', '[': ']', '{': '}' };

    for (const char of input) {
      if (openBrackets.includes(char)) {
        stack.push(char);
      } else if (closeBrackets.includes(char)) {
        if (stack.length === 0 || matchingBrackets[stack.pop()!] !== char) {
          return false;
        }
      }
    }

    return stack.length === 0;
};
// @openarc:end matchingBrackets.isPaired

export function isPaired(input: string): boolean {
  const stack: string[] = [];
  const openBrackets = '([{';
  const closeBrackets = ')]}';
  const bracketPairs: { [key: string]: string } = {
    ')': '(',
    ']': '[',
    '}': '{'
  };

  for (let char of input) {
    if (openBrackets.includes(char)) {
      stack.push(char);
    } else if (closeBrackets.includes(char)) {
      if (stack.length === 0 || stack.pop() !== bracketPairs[char]) {
        return false;
      }
    }
  }

  return stack.length === 0;
}

