// @openarc:begin rectangles.count
export const count: CountFn = (rows) => {
  return rows.reduce((count, row, i) => {
    return row.split('').reduce((count, char, j) => {
      if (char === '+') {
        const bottom = rows[i + 1]?.[j];
        const right = row[j + 1];
        if (bottom === '-' && right === '-') {
          let width = 1;
          let height = 1;
          while (rows[i + height]?.[j] === '|' && rows[i + height]?.[j + width] === '-') {
            height++;
          }
          while (row[j + width] === '-' && rows[i + 1]?.[j + width] === '|') {
            width++;
          }
          count += (width - 1) * (height - 1);
        }
      }
      return count;
    }, count);
  }, 0);
};
// @openarc:end rectangles.count

export function count(rows: string[]): number {
  if (rows.length === 0 || rows[0].length === 0) return 0;

  const width = rows[0].length;
  const height = rows.length;
  const visited: boolean[][] = Array.from({ length: height }, () => Array(width).fill(false));

  function isRectangle(x1: number, y1: number, x2: number, y2: number): boolean {
    if (x1 >= x2 || y1 >= y2) return false;
    for (let y = y1; y <= y2; y++) {
      for (let x = x1; x <= x2; x++) {
        if (rows[y][x] !== ' ' && rows[y][x] !== '+' && rows[y][x] !== '-' && rows[y][x] !== '|') {
          return false;
        }
      }
    }
    return true;
  }

  function dfs(x: number, y: number): void {
    if (x < 0 || x >= width || y < 0 || y >= height || visited[y][x] || rows[y][x] === ' ') return;
    visited[y][x] = true;
    dfs(x + 1, y);
    dfs(x - 1, y);
    dfs(x, y + 1);
    dfs(x, y - 1);
  }

  let rectangleCount = 0;

  for (let y = 0; y < height; y++) {
    for (let x = 0; x < width; x++) {
      if (!visited[y][x] && rows[y][x] === '+') {
        for (let y2 = y + 1; y2 < height; y2++) {
          for (let x2 = x + 1; x2 < width; x2++) {
            if (rows[y2][x2] === '+' && isRectangle(x, y, x2, y2)) {
              rectangleCount++;
              dfs(x, y);
            }
          }
        }
      }
    }
  }

  return rectangleCount;
}

