// @openarc:begin variableLengthQuantity.encode
export const encode: EncodeFn = (numbers) => {
  const result = [];
  for (let number of numbers) {
    let byte = number & 0x7F;
    number >>>= 7;
    while (number > 0) {
      result.push(byte | 0x80);
      byte = number & 0x7F;
      number >>>= 7;
    }
    result.push(byte);
  }
  return result;
};
