export function encode(numbers: number[]): number[] {
  const result: number[] = [];

  for (const number of numbers) {
    let value = number;
    const bytes: number[] = [];

    do {
      let byte = value & 0x7F; // Get the last 7 bits
      value >>>= 7; // Shift right by 7 bits

      if (value > 0) {
        byte |= 0x80; // Set the continuation bit
      }

      bytes.push(byte);
    } while (value > 0);

    result.push(...bytes);
  }

  return result;
}

export function decode(bytes: number[]): number[] {
  const result: number[] = [];
  let currentNumber = 0;
  let shift = 0;

  for (const byte of bytes) {
    const value = byte & 0x7F; // Get the last 7 bits
    currentNumber |= value << shift;

    if ((byte & 0x80) === 0) {
      // If the continuation bit is not set, we've reached the end of this number
      result.push(currentNumber);
      currentNumber = 0;
      shift = 0;
    } else {
      shift += 7;
    }
  }

  return result;
}

