// @openarc:begin diamond.makeDiamond
export const makeDiamond: MakeDiamondFn = (character) => {
  const charCode = character.charCodeAt(0);
  const diamondSize = charCode - 64;
  let result = '';
  for (let i = 1; i <= diamondSize; i++) {
      const spaces = ' '.repeat(diamondSize - i);
      const letter = String.fromCharCode(64 + i);
      const innerSpaces = i > 1 ? ' '.repeat(2 * i - 3) : '';
      result += spaces + letter + innerSpaces + (i > 1 ? letter : '') + spaces + '\n';
    }
  for (let i = diamondSize - 1; i >= 1; i--) {
      const spaces = ' '.repeat(diamondSize - i);
      const letter = String.fromCharCode(64 + i);
      const innerSpaces = ' '.repeat(2 * i - 3);
      result += spaces + letter + innerSpaces + letter + spaces + '\n';
    }
  return result;
};
// @openarc:end diamond.makeDiamond

export function makeDiamond(character: string): string {
  const charCode = character.charCodeAt(0);
  const size = charCode - 65 + 1;
  let result = '';

  for (let i = 0; i < size; i++) {
    const currentChar = String.fromCharCode(65 + i);
    const spaces = ' '.repeat(size - i - 1);
    const innerSpaces = i > 0 ? ' '.repeat(2 * i - 1) : '';
    result += `${spaces}${currentChar}${innerSpaces}${currentChar}${spaces}\n`;
  }

  for (let i = size - 2; i >= 0; i--) {
    const currentChar = String.fromCharCode(65 + i);
    const spaces = ' '.repeat(size - i - 1);
    const innerSpaces = i > 0 ? ' '.repeat(2 * i - 1) : '';
    result += `${spaces}${currentChar}${innerSpaces}${currentChar}${spaces}\n`;
  }

  return result;
}

