export function verse(n: number): string {
  const animals = [
    {
      name: "fly",
      description: "I don't know why she swallowed the fly. Perhaps she'll die.",
    },
    {
      name: "spider",
      description: "It wriggled and jiggled and tickled inside her.",
      swallowed: "fly",
    },
    {
      name: "bird",
      description: "How absurd to swallow a bird!",
      swallowed: "spider",
    },
    {
      name: "cat",
      description: "Imagine that, to swallow a cat!",
      swallowed: "bird",
    },
    {
      name: "dog",
      description: "What a hog, to swallow a dog!",
      swallowed: "cat",
    },
    {
      name: "goat",
      description: "Just opened her throat and swallowed a goat!",
      swallowed: "dog",
    },
    {
      name: "cow",
      description: "I don't know how she swallowed a cow!",
      swallowed: "goat",
    },
    {
      name: "horse",
      description: "She's dead, of course!",
    },
  ];

  if (n < 1 || n > animals.length) {
    throw new Error("Invalid verse number");
  }

  const animal = animals[n - 1];
  let result = `I know an old lady who swallowed a ${animal.name}.\n`;

  if (animal.name !== "horse") {
    result += `${animal.description}\n`;
    for (let i = n - 1; i > 0; i--) {
      const prevAnimal = animals[i - 1];
      result += `She swallowed the ${animal.name} to catch the ${prevAnimal.name}${
        prevAnimal.name === "fly" ? "" : " that wriggled and jiggled and tickled inside her"
      }.\n`;
    }
  }

  result += "I don't know why she swallowed the fly. Perhaps she'll die.\n";
  return result;
}

