export const annotate: AnnotateFn = (field) => {
  const rows = field.length;
  const cols = field[0]?.length || 0;
  const result: string[] = [];
  for (let i = 0; i < rows; i++) {
      let row = '';
      for (let j = 0; j < cols; j++) {
        if (field[i][j] === '*') {
          row += '*';
        } else {
          let count = 0;
          for (let di = -1; di <= 1; di++) {
            for (let dj = -1; dj <= 1; dj++) {
              if (di === 0 && dj === 0) continue;
              const ni = i + di;
              const nj = j + dj;
              if (ni >= 0 && ni < rows && nj >= 0 && nj < cols && field[ni][nj] === '*') {
                count++;
              }
            }
          }
          row += count > 0 ? count.toString() : ' ';
        }
      }
      result.push(row);
    }
  return result;
};
