// @openarc:begin phoneNumber.clean
export const clean: CleanFn = (input) => {
  return input.replace(/[^0-9]/g, '')
};
// @openarc:end phoneNumber.clean

export function clean(input: string): string {
  // Remove all non-digit characters
  let digits = input.replace(/\D/g, '');

  // Check if the number starts with '1' (country code)
  if (digits.startsWith('1')) {
    digits = digits.slice(1);
  }

  // Check if the resulting string has exactly 10 digits
  if (digits.length !== 10) {
    throw new Error("Invalid phone number");
  }

  // Check if the first digit is between 2 and 9
  if (digits[0] < '2' || digits[0] > '9') {
    throw new Error("Invalid area code");
  }

  return digits;
}

