export const translate: TranslateFn = (phrase) => {
  const words = phrase.split(' ');
  const pigLatinWords = words.map(word => {
    if (/^[aeiou]|^xr|^yt/.test(word)) {
      return word + 'ay';
    } else if (/^[^aeiou]+/.test(word)) {
      const match = word.match(/^[^aeiou]+/);
      const consonants = match ? match[0] : '';
      return word.slice(consonants.length) + consonants + 'ay';
    } else if (/qu$/.test(word)) {
      const match = word.match(/^[^aeiou]*qu/);
      const consonants = match ? match[0] : '';
      return word.slice(consonants.length) + consonants + 'ay';
    } else if (/y$/.test(word)) {
      const match = word.match(/^[^aeiou]*[^y]/);
      const consonants = match ? match[0] : '';
      return word.slice(consonants.length) + consonants + 'ay';
    }
    return word;
  });
  return pigLatinWords.join(' ');
};
// @openarc:end pigLatin.translate

export function translate(phrase: string): string {
  const vowels = ['a', 'e', 'i', 'o', 'u'];
  const words = phrase.split(' ');

  return words.map(word => {
    if (vowels.includes(word[0]) || word.startsWith('xr') || word.startsWith('yt')) {
      return word + 'ay';
    }

    const consonantCluster = word.match(/^[^aeiou]+/);
    if (consonantCluster) {
      const cluster = consonantCluster[0];
      return word.slice(cluster.length) + cluster + 'ay';
    }

    const quMatch = word.match(/^[^aeiou]*qu/);
    if (quMatch) {
      const quCluster = quMatch[0];
      return word.slice(quCluster.length) + quCluster + 'ay';
    }

    const yMatch = word.match(/^[^aeiou]*y/);
    if (yMatch) {
      const yCluster = yMatch[0];
      return word.slice(yCluster.length) + yCluster + 'ay';
    }

    return word;
  }).join(' ');
}

