export const transpose: TransposeFn = (rows) => {
  const maxLength = Math.max(...rows.map(row => row.length));
    const paddedRows = rows.map(row => row.padEnd(maxLength));
    const transposed: string[] = [];
    for (let i = 0; i < maxLength; i++) {
      let newRow = '';
      for (let j = 0; j < paddedRows.length; j++) {
        newRow += paddedRows[j][i];
      }
      transposed.push(newRow);
    }
    return transposed;
};
// @openarc:end transpose.transpose

export function transpose(rows: string[]): string[] {
  if (rows.length === 0) return [];

  // Find the maximum length of the rows
  const maxLength = Math.max(...rows.map(row => row.length));

  // Pad each row to the maximum length with spaces
  const paddedRows = rows.map(row => row.padEnd(maxLength, ' '));

  // Initialize the transposed array
  const transposed: string[] = [];

  // Iterate over each column index
  for (let col = 0; col < maxLength; col++) {
    let newRow = '';
    // Iterate over each row index
    for (let row = 0; row < paddedRows.length; row++) {
      newRow += paddedRows[row][col];
    }
    // Trim trailing spaces from the new row
    transposed.push(newRow.replace(/\s+$/, ''));
  }

  return transposed;
}

