        "What is 53 plus 2?"
      ],
      "expected": 55
    }
  ]
});

// @openarc:begin wordy.answer
export const answer: AnswerFn = (question) => arc.todo("wordy.answer");
// @openarc:end wordy.answer

export function answer(question: string): number {
  if (!question.startsWith("What is ")) {
    throw new Error("Unsupported operation or non-math question");
  }

  const expression = question
    .replace("What is ", "")
    .replace("?", "")
    .replace(/ plus /g, " + ")
    .replace(/ minus /g, " - ")
    .replace(/ multiplied by /g, " * ")
    .replace(/ divided by /g, " / ");

  try {
    const result = eval(expression);
    if (typeof result !== "number" || isNaN(result) || !isFinite(result)) {
      throw new Error("Invalid result");
    }
    return Math.trunc(result);
  } catch (error) {
    throw new Error("Invalid syntax or unsupported operation");
  }
}

