    let top = 0;
    let bottom = size - 1;
    let left = 0;
    let right = size - 1;

    while (num <= size * size) {
      for (let i = left; i <= right; i++) {
        matrix[top][i] = num++;
      }
      top++;

      for (let i = top; i <= bottom; i++) {
        matrix[i][right] = num++;
      }
      right--;

      for (let i = right; i >= left; i--) {
        matrix[bottom][i] = num++;
      }
      bottom--;

      for (let i = bottom; i >= top; i--) {
        matrix[i][left] = num++;
      }
      left++;
    }

