export const translate: TranslateFn = (phrase) => {
  return phrase.split(' ').map(word => {
      const vowels = 'aeiou';
      const isVowel = (char: string) => vowels.includes(char);

      // Check for special starting patterns: 'xr' or 'yt'
      if (word.startsWith('xr') || word.startsWith('yt')) {
        return word + 'ay';
      }

      // Check if word starts with a vowel
      if (isVowel(word[0])) {
        return word + 'ay';
      }

      // Find the split point for consonants
      let i = 0;
      while (i < word.length) {
        const char = word[i];

        // Rule 3: Handle 'qu' as a unit
        if (char === 'q' && i + 1 < word.length && word[i + 1] === 'u') {
          i += 2;
          break;
        }

        // Rule 4: Handle 'y' as a vowel if preceded by consonants
        if (char === 'y' && i > 0) {
          break;
        }

        // If it's a vowel, stop here
        if (isVowel(char)) {
          break;
        }

        // If it's a consonant, continue
        i++;
      }

      // Move the consonant cluster to the end and add 'ay'
      return word.slice(i) + word.slice(0, i) + 'ay';
