export function translate(phrase: string): string {
  if (!phrase || typeof phrase !== "string") {
    return phrase;
  }

  const vowels = new Set(["a", "e", "i", "o", "u"]);

  const translateWord = (word: string): string => {
    // Rule 1: Starts with vowel, "xr", or "yt"
    if (vowels.has(word[0].toLowerCase())) {
      return word + "ay";
    }

    if (word.startsWith("xr") || word.startsWith("yt")) {
      return word + "ay";
    }

    // Rule 3: Starts with consonants followed by "qu"
    // We check for "qu" specifically before general consonant clusters to handle the 'u' correctly.
    const quIndex = word.indexOf("qu");
    if (quIndex !== -1) {
      // Move everything up to and including "qu" to the end
      const prefix = word.substring(0, quIndex);
      const suffix = word.substring(quIndex);
      return suffix + prefix + "ay";
    }

    // Rule 4: Starts with consonants followed by "y"
    // We need to find the first 'y' that acts as a vowel (i.e., not at index 0).
    // If 'y' is at index 0, it acts as a consonant (handled by Rule 1 logic implicitly or general consonant rule).
    // If 'y' appears later, it splits the word.
    const yIndex = word.indexOf("y");
    if (yIndex !== -1 && yIndex > 0) {
      const prefix = word.substring(0, yIndex);
      const suffix = word.substring(yIndex);
      return suffix + prefix + "ay";
    }

    // Rule 2: Starts with one or more consonants (and no special 'qu' or 'y' cases handled above)
    // Find the first vowel
    let vowelIndex = -1;
    for (let i = 0; i < word.length; i++) {
      if (vowels.has(word[i].toLowerCase())) {
        vowelIndex = i;
        break;
      }
    }

    if (vowelIndex !== -1) {
      const prefix = word.substring(0, vowelIndex);
      const suffix = word.substring(vowelIndex);
      return suffix + prefix + "ay";
    }

    // Fallback for words with no vowels (e.g., "my" handled by Rule 4, but "rhythm" handled by Rule 4)
    // If no vowels found, treat whole word as consonant cluster
    return word + "ay";
  };

  return phrase
    .split(" ")
    .map(translateWord)
    .join(" ");
}

