export const count: CountFn = (rows) => {
  const n = rows.length;
  const m = rows[0]?.length ?? 0;
  let count = 0;
  for (let r1 = 0; r1 < n; r1++) {
    for (let r2 = r1 + 1; r2 < n; r2++) {
      for (let c1 = 0; c1 < m; c1++) {
        for (let c2 = c1 + 1; c2 < m; c2++) {
          if (rows[r1][c1] === '+' && rows[r1][c2] === '+' &&
              rows[r2][c1] === '+' && rows[r2][c2] === '+' &&
              rows[r1][c1 + 1] === '-' && rows[r1][c2 - 1] === '-' &&
              rows[r2][c1 + 1] === '-' && rows[r2][c2 - 1] === '-') {
            count++;
          }
        }
      }
    }
  }
  return count;
};
// @openarc:end rectangles.count

export function count(rows: string[]): number {
  if (rows.length === 0) return 0;

  const numCols = rows[0].length;
  if (numCols === 0) return 0;

  // Convert rows into a 2D array of characters for easier access
  const grid: string[][] = rows.map(row => row.split(''));

  let rectangleCount = 0;

  // Iterate over all possible top-left corners (r1, c1)
  for (let r1 = 0; r1 < rows.length; r1++) {
    for (let c1 = 0; c1 < numCols; c1++) {
      // Only consider '+' as a potential top-left corner
      if (grid[r1][c1] !== '+') continue;

      // Iterate over all possible bottom-right corners (r2, c2)
      for (let r2 = r1; r2 < rows.length; r2++) {
        for (let c2 = c1; c2 < numCols; c2++) {
          // Check if the current pair of points (r1, c1) and (r2, c2) can form a rectangle
          // A valid rectangle must have '+' at all four corners
          if (grid[r1][c2] !== '+' || grid[r2][c1] !== '+' || grid[r2][c2] !== '+') {
            continue;
          }

          // Check the top edge between (r1, c1) and (r1, c2)
          let topEdgeValid = true;
          for (let c = c1 + 1; c < c2; c++) {
            if (grid[r1][c] !== '-') {
              topEdgeValid = false;
              break;
            }
          }

          // Check the bottom edge between (r2, c1) and (r2, c2)
          let bottomEdgeValid = true;
          for (let c = c1 + 1; c < c2; c++) {
            if (grid[r2][c] !== '-') {
              bottomEdgeValid = false;
              break;
            }
          }

          // Check the left edge between (r1, c1) and (r2, c1)
          let leftEdgeValid = true;
          for (let r = r1 + 1; r < r2; r++) {
            if (grid[r][c1] !== '|') {
              leftEdgeValid = false;
              break;
            }
          }

          // Check the right edge between (r1, c2) and (r2, c2)
          let rightEdgeValid = true;
          for (let r = r1 + 1; r < r2; r++) {
            if (grid[r][c2] !== '|') {
              rightEdgeValid = false;
              break;
            }
          }

          // If all edges are valid, increment the count
          if (topEdgeValid && bottomEdgeValid && leftEdgeValid && rightEdgeValid) {
            rectangleCount++;
          }
        }
      }
    }
  }

  return rectangleCount;
}

