export const encode: EncodeFn = (numbers) => {
  const result: number[] = [];
  for (const num of numbers) {
      let value = num;
      let byte = value & 0x7F;
      value >>= 7;
      if (value > 0) {
        byte |= 0x80;
      }
      result.push(byte);
      while (value > 0) {
        byte = value & 0x7F;
        value >>= 7;
        byte |= 0x80;
        result.push(byte);
      }
    }
