import * as arc from "open-arc";

export type AnswerFn = (question: string) => number;

export const answerSpec = arc.defineRegion<AnswerFn>({
  "id": "wordy.answer",
  "intent": [
    "Exercise \"wordy\": implement `answer`.",
    "Parse and evaluate simple math word problems returning the answer as an integer.",
    "## Iteration 0 — Numbers",
    "Problems with no operations simply evaluate to the number given.",
    "> What is 5?",
    "Evaluates to 5.",
    "## Iteration 1 — Addition",
    "Add two numbers together.",
    "> What is 5 plus 13?",
    "Evaluates to 18.",
    "Handle large numbers and negative numbers.",
    "## Iteration 2 — Subtraction, Multiplication and Division",
    "Now, perform the other three operations.",
    "> What is 7 minus 5?",
    "2",
    "> What is 6 multiplied by 4?",
    "24",
    "> What is 25 divided by 5?",
    "5",
    "## Iteration 3 — Multiple Operations",
    "Handle a set of operations, in sequence.",
    "Since these are verbal word problems, evaluate the expression from left-to-right, _ignoring the typical order of operations._",
    "> What is 5 plus 13 plus 6?",
    "24",
    "> What is 3 plus 2 multiplied by 3?",
    "15 (i.e. not 9)",
    "## Iteration 4 — Errors",
    "The parser should reject:",
    "- Unsupported operations (\"What is 52 cubed?\") - Non-math questions (\"Who is the President of the United States\") - Word problems with invalid syntax (\"What is 1 plus plus 2?\")"
  ],
  "examples": [
    {
      "name": "Wordy > just a number",
      "args": [
        "What is 5?"
      ],
      "expected": 5
    },
    {
      "name": "Wordy > addition",
      "args": [
        "What is 1 plus 1?"
      ],
      "expected": 2
    },
    {
      "name": "Wordy > more addition",
      "args": [
        "What is 53 plus 2?"
      ],
      "expected": 55
    }
  ]
});

// @openarc:begin wordy.answer
export const answer: AnswerFn = (question) => {
  const trimmed = question.trim();
  if (!trimmed.startsWith('What is ')) {
      throw new Error('Invalid question format');
    }
  const expression = trimmed.slice(8).replace('?', '').trim();
  const parts = expression.split(/\s+/);
  if (parts.length === 0) {
      throw new Error('Empty expression');
    }
  let result = parseFloat(parts[0]);
  if (isNaN(result)) {
      throw new Error('Invalid number');
    }
  for (let i = 1; i < parts.length; i += 2) {
      const operator = parts[i];
      const nextValue = parseFloat(parts[i + 1]);
      if (isNaN(nextValue)) {
        throw new Error('Invalid number');
      }
      if (i + 1 >= parts.length) {
        throw new Error('Missing operand');
      }
      switch (operator) {
        case 'plus':
          result += nextValue;
          break;
        case 'minus':
          result -= nextValue;
          break;
        case 'multiplied by':
          result *= nextValue;
          break;
        case 'divided by':
          if (nextValue === 0) {
            throw new Error('Division by zero');
          }
          result /= nextValue;
          break;
        default:
          throw new Error(`Unsupported operation: ${operator}`);
      }
    }
  return Math.round(result);
};
// @openarc:end wordy.answer

export function answer(question: string): number {
  // Remove surrounding whitespace
  const trimmed = question.trim();

  // Expected format: "What is <expression>?"
  if (!trimmed.startsWith("What is ") || !trimmed.endsWith("?")) {
    throw new Error("Unknown operation");
  }

  // Extract the expression part between "What is " and "?"
  const expression = trimmed.slice(8, -1).trim();

  if (!expression) {
    throw new Error("Unknown operation");
  }

  // Tokenize the expression
  // We need to handle numbers (including negatives) and keywords.
  // Strategy: Scan character by character to build tokens.

  const keywords = [
    { word: "plus", op: "+" },
    { word: "minus", op: "-" },
    { word: "multiplied", op: null }, // "by" follows
    { word: "by", op: null },
    { word: "divided", op: null }, // "by" follows
    { word: "cubed", op: null },
    { word: "raised", op: null },
    { word: "to", op: null }
  ];

  const tokens: (number | string)[] = [];
  let i = 0;
  const len = expression.length;

  while (i < len) {
    const char = expression[i];

    // Check for number start (digit or minus sign)
    if (/\d/.test(char)) {
      let numStr = "";
      while (i < len && /\d/.test(expression[i])) {
        numStr += expression[i];
        i++;
      }
      tokens.push(parseInt(numStr, 10));
    } else if (char === "-") {
      // Check if it's a unary minus (start of a negative number)
      // It is a unary minus if it's at the start or follows an operator.
      // However, in our token stream, we just need to know if we are expecting a number.
      // If we see '-' and the previous token was not a number (or it's the start), it's a unary minus.
      // But wait, "5 minus 5". After '5', there is a space.
      // So if we see '-', it must be preceded by a space or be at start.
      // If it is preceded by a space, it's a unary minus.
      // If it is preceded by a digit, it's a binary minus operator.
      // But my loop skips spaces? No, I need to handle spaces.

      // Let's handle spaces explicitly.
      if (expression[i - 1] === " ") {
        // It's a unary minus
        let numStr = "-";
        while (i < len && /\d/.test(expression[i])) {
          numStr += expression[i];
          i++;
        }
        tokens.push(parseInt(numStr, 10));
      } else {
        // It's a binary minus operator
        tokens.push("-");
        i++;
      }
    } else if (/[a-z]/.test(char)) {
      // It's a word
      let word = "";
      while (i < len && /[a-z]/.test(expression[i])) {
        word += expression[i];
        i++;
      }

      // Check if it's a known operator word
      const found = keywords.find(k => k.word === word);
      if (found) {
        tokens.push(found.word);
      } else {
        // Unknown word -> Invalid syntax
        throw new Error("Unknown operation");
      }
    } else if (char === " ") {
      // Skip spaces
      i++;
    } else {
      // Unknown character
      throw new Error("Unknown operation");
    }
  }

  // Now we have a list of tokens: numbers and operator strings.
  // We need to evaluate left-to-right.

  // Check for "multiplied by"
  // The tokenizer produces ["multiplied", "by"] as two separate tokens.
  // We need to handle this.

  const processedTokens: (number | string)[] = [];

  for (let k = 0; k < tokens.length; k++) {
    const token = tokens[k];

    if (typeof token === "number") {
      processedTokens.push(token);
    } else if (token === "plus") {
      processedTokens.push("+");
    } else if (token === "minus") {
      processedTokens.push("-");
    } else if (token === "multiplied") {
      // Look ahead for "by"
      if (k + 1 < tokens.length && tokens[k + 1] === "by") {
        processedTokens.push("*");
        k++; // Skip "by"
      } else {
        throw new Error("Unknown operation");
      }
    } else if (token === "divided") {
      // Look ahead for "by"
      if (k + 1 < tokens.length && tokens[k + 1] === "by") {
        processedTokens.push("/");
        k++; // Skip "by"
      } else {
        throw new Error("Unknown operation");
      }
    } else if (token === "cubed") {
      throw new Error("Unknown operation");
    } else if (token === "raised") {
      // "raised to"
      if (k + 1 < tokens.length && tokens[k + 1] === "to") {
        throw new Error("Unknown operation");
      } else {
        throw new Error("Unknown operation");
      }
    } else if (token === "to") {
      throw new Error("Unknown operation");
    } else {
      throw new Error("Unknown operation");
    }
  }

  // Now evaluate left-to-right
  if (processedTokens.length === 0) {
    throw new Error("Unknown operation");
  }

  // The first token must be a number
  if (typeof processedTokens[0] !== "number") {
    throw new Error("Unknown operation");
  }

  let result = processedTokens[0];

  for (let k = 1; k < processedTokens.length; k += 2) {
    const op = processedTokens[k];
    const nextNum = processedTokens[k + 1];

    if (typeof nextNum !== "number") {
      throw new Error("Unknown operation");
    }

    if (op === "+") {
      result += nextNum;
    } else if (op === "-") {
      result -= nextNum;
    } else if (op === "*") {
      result *= nextNum;
    } else if (op === "/") {
      // Integer division? The examples show 25 / 5 = 5.
      // Usually word problems imply integer division or exact division.
      // If result is not integer, we might need to handle it.
      // But the return type is number.
      // Let's use standard division.
      result /= nextNum;
    } else {
      throw new Error("Unknown operation");
    }
  }

  return result;
}

