// @openarc:begin diamond.makeDiamond
export const makeDiamond: MakeDiamondFn = (character) => {
  const input = character.toUpperCase();
  const code = input.charCodeAt(0);
  const aCode = 'A'.charCodeAt(0);
  const n = code - aCode;
  let result = '';
  for (let i = 0; i <= n; i++) {
    const spaces = ' '.repeat(n - i);
    const row = spaces + String.fromCharCode(aCode + i) + (i > 0 ? ' ' + String.fromCharCode(aCode + i) : '') + spaces;
    result += row + '\n';
  }
  for (let i = n - 1; i >= 0; i--) {
    const spaces = ' '.repeat(n - i);
    const row = spaces + String.fromCharCode(aCode + i) + (i > 0 ? ' ' + String.fromCharCode(aCode + i) : '') + spaces;
    result += row + '\n';
  }
  return result;
};
// @openarc:end diamond.makeDiamond

export function makeDiamond(character: string): string {
  const input = character.toUpperCase().trim();

  if (input.length !== 1 || !/^[A-Z]$/.test(input)) {
    throw new Error("Input must be a single uppercase letter A-Z");
  }

  const startChar = 'A'.charCodeAt(0);
  const endChar = input.charCodeAt(0);
  const n = endChar - startChar; // 0 for 'A', 2 for 'C', etc.

  const lines: string[] = [];

  // Generate top half (including the middle row)
  for (let i = 0; i <= n; i++) {
    const currentChar = String.fromCharCode(startChar + i);
    const spaces = ' '.repeat(n - i);

    if (i === 0) {
      // First row: just the letter A
      lines.push(spaces + currentChar + spaces);
    } else {
      // Other rows: letter, spaces, letter
      const innerSpaces = ' '.repeat(2 * i - 1);
      lines.push(spaces + currentChar + innerSpaces + currentChar + spaces);
    }
  }

  // Generate bottom half (mirror of top half, excluding the middle row)
  for (let i = n - 1; i >= 0; i--) {
    lines.push(lines[i]);
  }

  return lines.join('\n') + '\n';
}

