import * as arc from "open-arc";

export type CleanFn = (input: string) => string;

export const cleanSpec = arc.defineRegion<CleanFn>({
  "id": "phoneNumber.clean",
  "intent": [
    "Exercise \"phone-number\": implement `clean`.",
    "Clean up phone numbers so that they can be sent SMS messages.",
    "The **North American Numbering Plan (NANP)** is a telephone numbering system used by many countries in North America like the United States, Canada or Bermuda. All NANP-countries share the same international country code: `1`.",
    "NANP numbers are ten-digit numbers consisting of a three-digit Numbering Plan Area code, commonly known as _area code_, followed by a seven-digit local number. The first three digits of the local number represent the _exchange code_, followed by the unique four-digit number which is the _subscriber number_.",
    "The format is usually represented as",
    "```text NXX NXX-XXXX ```",
    "where `N` is any digit from 2 through 9 and `X` is any digit from 0 through 9.",
    "Sometimes they also have the country code (represented as `1` or `+1`) prefixed.",
    "Your task is to clean up differently formatted telephone numbers by removing punctuation and the country code if present.",
    "For example, the inputs",
    "- `+1 (613)-995-0253` - `613-995-0253` - `1 613 995 0253` - `613.995.0253`",
    "should all produce the output",
    "`6139950253`",
    "**Note:** As this exercise only deals with telephone numbers used in NANP-countries, only 1 is considered a valid country code."
  ],
  "examples": [
    {
      "name": "Phone Number > Cleanup user-entered phone numbers > cleans the number",
      "args": [
        "(223) 456-7890"
      ],
      "expected": "2234567890"
    },
    {
      "name": "Phone Number > Cleanup user-entered phone numbers > cleans numbers with dots",
      "args": [
        "223.456.7890"
      ],
      "expected": "2234567890"
    }
  ]
});

// @openarc:begin phoneNumber.clean
export const clean: CleanFn = (input) => {
  const cleaned = input.replace(/[^0-9]/g, '');
  if (cleaned.length === 10) {
      return cleaned;
    }
  if (cleaned.length === 11 && cleaned.startsWith('1')) {
      return cleaned.slice(1);
    }
  throw new Error('Invalid phone number');
};
// @openarc:end phoneNumber.clean

export function clean(input: string): string {
  // Remove all non-digit characters
  const digits = input.replace(/\D/g, "");

  // Handle country code
  if (digits.startsWith("1")) {
    digits = digits.slice(1);
  }

  // Validate length
  if (digits.length !== 10) {
    throw new Error("Incorrect phone number length");
  }

  // Validate area code and exchange code (must start with 2-9)
  const firstDigit = parseInt(digits[0], 10);
  const secondDigit = parseInt(digits[1], 10);

  if (firstDigit < 2 || secondDigit < 2) {
    throw new Error("Incorrect phone number format");
  }

  return digits;
}

import * as arc from "open-arc";

export type TranslateFn = (phrase: string) => string;

export const translateSpec = arc.defineRegion<TranslateFn>({
  "id": "pigLatin.translate",
  "intent": [
    "Exercise \"pig-latin\": implement `translate`.",
    "Your task is to translate text from English to Pig Latin. The translation is defined using four rules, which look at the pattern of vowels and consonants at the beginning of a word. These rules look at each word's use of vowels and consonants:",
    "- vowels: the letters `a`, `e`, `i`, `o`, and `u` - consonants: the other 21 letters of the English alphabet",
    "## Rule 1",
    "If a word begins with a vowel, or starts with `\"xr\"` or `\"yt\"`, add an `\"ay\"` sound to the end of the word.",
    "For example:",
    "- `\"apple\"` -> `\"appleay\"` (starts with vowel) - `\"xray\"` -> `\"xrayay\"` (starts with `\"xr\"`) - `\"yttria\"` -> `\"yttriaay\"` (starts with `\"yt\"`)",
    "## Rule 2",
    "If a word begins with one or more consonants, first move those consonants to the end of the word and then add an `\"ay\"` sound to the end of the word.",
    "For example:",
    "- `\"pig\"` -> `\"igp\"` -> `\"igpay\"` (starts with single consonant) - `\"chair\"` -> `\"airch\"` -> `\"airchay\"` (starts with multiple consonants) - `\"thrush\"` -> `\"ushthr\"` -> `\"ushthray\"` (starts with multiple consonants)",
    "## Rule 3",
    "If a word starts with zero or more consonants followed by `\"qu\"`, first move those consonants (if any) and the `\"qu\"` part to the end of the word, and then add an `\"ay\"` sound to the end of the word.",
    "For example:",
    "- `\"quick\"` -> `\"ickqu\"` -> `\"ickquay\"` (starts with `\"qu\"`, no preceding consonants) - `\"square\"` -> `\"aresqu\"` -> `\"aresquay\"` (starts with one consonant followed by `\"qu`\")",
    "## Rule 4",
    "If a word starts with one or more consonants followed by `\"y\"`, first move the consonants preceding the `\"y\"`to the end of the word, and then add an `\"ay\"` sound to the end of the word.",
    "Some examples:",
    "- `\"my\"` -> `\"ym\"` -> `\"ymay\"` (starts with single consonant followed by `\"y\"`) - `\"rhythm\"` -> `\"ythmrh\"` -> `\"ythmrhay\"` (starts with multiple consonants followed by `\"y\"`)"
  ],
  "examples": [
    {
      "name": "ay is added to words that start with vowels > word beginning with a",
      "args": [
        "apple"
      ],
      "expected": "appleay"
    },
    {
      "name": "ay is added to words that start with vowels > word beginning with e",
      "args": [
        "ear"
      ],
      "expected": "earay"
    },
    {
      "name": "ay is added to words that start with vowels > word beginning with i",
      "args": [
        "igloo"
      ],
      "expected": "iglooay"
    }
  ]
});

// @openarc:begin pigLatin.translate
export const translate: TranslateFn = (phrase) => {
  return phrase.split(' ').map(word => {
      const vowels = 'aeiou';
      const isVowel = (char: string) => vowels.includes(char);

      // Check for special starting patterns: 'xr' or 'yt'
      if (word.startsWith('xr') || word.startsWith('yt')) {
        return word + 'ay';
      }

      // Check if word starts with a vowel
      if (isVowel(word[0])) {
        return word + 'ay';
      }

      // Find the split point for consonants
      let i = 0;

      // Handle 'qu' as a unit
      if (word[i] === 'q' && word[i + 1] === 'u') {
        i = 2;
      } else {
        // Move consonants until a vowel or 'y' (if preceded by consonants)
        while (i < word.length && !isVowel(word[i])) {
          i++;
        }
      }

      // Special case for 'y': if it's the first letter, treat as vowel. 
      // If preceded by consonants, treat as vowel for splitting.
      // The logic above handles 'y' as a vowel if we reach it.
      // However, we need to ensure 'y' is treated as a consonant if it's the first letter? 
      // Rule 4 says: consonants followed by 'y'. If word is 'my', 'm' is consonant, 'y' is the split point.
      // If word is 'yellow', 'y' is first letter -> vowel case (Rule 1). 
      // My loop condition !isVowel(word[i]) treats 'y' as non-vowel. 
      // So for 'yellow', i=0, isVowel('y') is false. Loop continues? 
      // We need to handle 'y' at index 0 as a vowel.
      if (i === 0 && word[0] === 'y') {
        return word + 'ay';
      }

      // If we are here, 'y' inside the consonant cluster acts as the vowel trigger.
      // The loop stops at 'y'.

      return word.slice(i) + word.slice(0, i) + 'ay';
    }).join(' ');
};
// @openarc:end pigLatin.translate

export function translate(phrase: string): string {
  if (!phrase || typeof phrase !== "string") {
    return phrase;
  }

  const vowels = new Set(["a", "e", "i", "o", "u"]);

  const translateWord = (word: string): string => {
    // Rule 1: Starts with vowel, "xr", or "yt"
    if (vowels.has(word[0].toLowerCase())) {
      return word + "ay";
    }

    if (word.startsWith("xr") || word.startsWith("yt")) {
      return word + "ay";
    }

    // Rule 3: Starts with consonants followed by "qu"
    // We check for "qu" specifically before general consonant clusters to handle the 'u' correctly.
    const quIndex = word.indexOf("qu");
    if (quIndex !== -1) {
      // Move everything up to and including "qu" to the end
      const prefix = word.substring(0, quIndex);
      const suffix = word.substring(quIndex);
      return suffix + prefix + "ay";
    }

    // Rule 4: Starts with consonants followed by "y"
    // We need to find the first 'y' that acts as a vowel (i.e., not at index 0).
    // If 'y' is at index 0, it acts as a consonant (handled by Rule 1 logic implicitly or general consonant rule).
    // If 'y' appears later, it splits the word.
    const yIndex = word.indexOf("y");
    if (yIndex !== -1 && yIndex > 0) {
      const prefix = word.substring(0, yIndex);
      const suffix = word.substring(yIndex);
      return suffix + prefix + "ay";
    }

    // Rule 2: Starts with one or more consonants (and no special 'qu' or 'y' cases handled above)
    // Find the first vowel
    let vowelIndex = -1;
    for (let i = 0; i < word.length; i++) {
      if (vowels.has(word[i].toLowerCase())) {
        vowelIndex = i;
        break;
      }
    }

    if (vowelIndex !== -1) {
      const prefix = word.substring(0, vowelIndex);
      const suffix = word.substring(vowelIndex);
      return suffix + prefix + "ay";
    }

    // Fallback for words with no vowels (e.g., "my" handled by Rule 4, but "rhythm" handled by Rule 4)
    // If no vowels found, treat whole word as consonant cluster
    return word + "ay";
  };

  return phrase
    .split(" ")
    .map(translateWord)
    .join(" ");
}

import * as arc from "open-arc";

export type CountFn = (rows: string[]) => number;

export const countSpec = arc.defineRegion<CountFn>({
  "id": "rectangles.count",
  "intent": [
    "Exercise \"rectangles\": implement `count`.",
    "Count the rectangles in an ASCII diagram like the one below.",
    "```text +--+ ++  | +-++--+ |  |  | +--+--+ ```",
    "The above diagram contains these 6 rectangles:",
    "```text",
    "+-----+ |     | +-----+ ```",
    "```text +--+ |  | |  | |  | +--+ ```",
    "```text +--+ |  | +--+",
    "```",
    "```text",
    "+--+ |  | +--+ ```",
    "```text",
    "+--+ |  | +--+ ```",
    "```text",
    "++ ++",
    "```",
    "You may assume that the input is always a proper rectangle (i.e. the length of every line equals the length of the first line)."
  ],
  "examples": [
    {
      "name": "Rectangles > no rows",
      "args": [
        []
      ],
      "expected": 0
    },
    {
      "name": "Rectangles > no columns",
      "args": [
        [
          ""
        ]
      ],
      "expected": 0
    },
    {
      "name": "Rectangles > no rectangles",
      "args": [
        [
          " "
        ]
      ],
      "expected": 0
    }
  ]
});

// @openarc:begin rectangles.count
export const count: CountFn = (rows) => {
  const n = rows.length;
  const m = rows[0]?.length ?? 0;
  let count = 0;
  for (let r1 = 0; r1 < n; r1++) {
    for (let r2 = r1 + 1; r2 < n; r2++) {
      for (let c1 = 0; c1 < m; c1++) {
        for (let c2 = c1 + 1; c2 < m; c2++) {
          if (rows[r1][c1] === '+' && rows[r1][c2] === '+' &&
              rows[r2][c1] === '+' && rows[r2][c2] === '+' &&
              rows[r1][c1 + 1] === '-' && rows[r1][c2 - 1] === '-' &&
              rows[r2][c1 + 1] === '-' && rows[r2][c2 - 1] === '-') {
            count++;
          }
        }
      }
    }
  }
  return count;
};
// @openarc:end rectangles.count

export function count(rows: string[]): number {
  if (rows.length === 0) return 0;

  const numCols = rows[0].length;
  if (numCols === 0) return 0;

  // Convert rows into a 2D array of characters for easier access
  const grid: string[][] = rows.map(row => row.split(''));

  let rectangleCount = 0;

  // Iterate over all possible top-left corners (r1, c1)
  for (let r1 = 0; r1 < rows.length; r1++) {
    for (let c1 = 0; c1 < numCols; c1++) {
      // Only consider '+' as a potential top-left corner
      if (grid[r1][c1] !== '+') continue;

      // Iterate over all possible bottom-right corners (r2, c2)
      for (let r2 = r1; r2 < rows.length; r2++) {
        for (let c2 = c1; c2 < numCols; c2++) {
          // Check if the current pair of points (r1, c1) and (r2, c2) can form a rectangle
          // A valid rectangle must have '+' at all four corners
          if (grid[r1][c2] !== '+' || grid[r2][c1] !== '+' || grid[r2][c2] !== '+') {
            continue;
          }

          // Check the top edge between (r1, c1) and (r1, c2)
          let topEdgeValid = true;
          for (let c = c1 + 1; c < c2; c++) {
            if (grid[r1][c] !== '-') {
              topEdgeValid = false;
              break;
            }
          }

          // Check the bottom edge between (r2, c1) and (r2, c2)
          let bottomEdgeValid = true;
          for (let c = c1 + 1; c < c2; c++) {
            if (grid[r2][c] !== '-') {
              bottomEdgeValid = false;
              break;
            }
          }

          // Check the left edge between (r1, c1) and (r2, c1)
          let leftEdgeValid = true;
          for (let r = r1 + 1; r < r2; r++) {
            if (grid[r][c1] !== '|') {
              leftEdgeValid = false;
              break;
            }
          }

          // Check the right edge between (r1, c2) and (r2, c2)
          let rightEdgeValid = true;
          for (let r = r1 + 1; r < r2; r++) {
            if (grid[r][c2] !== '|') {
              rightEdgeValid = false;
              break;
            }
          }

          // If all edges are valid, increment the count
          if (topEdgeValid && bottomEdgeValid && leftEdgeValid && rightEdgeValid) {
            rectangleCount++;
          }
        }
      }
    }
  }

  return rectangleCount;
}

