export function recite(startVerse: number, endVerse: number): string {
  const days = [
    "",
    "first",
    "second",
    "third",
    "fourth",
    "fifth",
    "sixth",
    "seventh",
    "eighth",
    "ninth",
    "tenth",
    "eleventh",
    "twelfth",
  ];

  const gifts = [
    "",
    "a Partridge in a Pear Tree",
    "two Turtle Doves",
    "three French Hens",
    "four Calling Birds",
    "five Gold Rings",
    "six Geese-a-Laying",
    "seven Swans-a-Swimming",
    "eight Maids-a-Milking",
    "nine Ladies Dancing",
    "ten Lords-a-Leaping",
    "eleven Pipers Piping",
    "twelve Drummers Drumming",
  ];

  const buildVerse = (n: number): string => {
    let verse = `On the ${days[n]} day of Christmas my true love gave to me: `;

    for (let i = n; i >= 1; i--) {
      if (i === 1 && n > 1) {
        verse += `and ${gifts[i]}, `;
      } else {
        verse += `${gifts[i]}, `;
      }
    }

    // Remove the trailing comma and space, then add the period
    return verse.slice(0, -2) + ".";
  };

  const verses: string[] = [];
  for (let i = startVerse; i <= endVerse; i++) {
    verses.push(buildVerse(i));
  }

  return verses.join("\n") + "\n";
}

