import * as arc from "open-arc";

export type AnswerFn = (question: string) => number;

export const answerSpec = arc.defineRegion<AnswerFn>({
  "id": "wordy.answer",
  "intent": [
    "Exercise \"wordy\": implement `answer`.",
    "Parse and evaluate simple math word problems returning the answer as an integer.",
    "## Iteration 0 — Numbers",
    "Problems with no operations simply evaluate to the number given.",
    "> What is 5?",
    "Evaluates to 5.",
    "## Iteration 1 — Addition",
    "Add two numbers together.",
    "> What is 5 plus 13?",
    "Evaluates to 18.",
    "Handle large numbers and negative numbers.",
    "## Iteration 2 — Subtraction, Multiplication and Division",
    "Now, perform the other three operations.",
    "> What is 7 minus 5?",
    "2",
    "> What is 6 multiplied by 4?",
    "24",
    "> What is 25 divided by 5?",
    "5",
    "## Iteration 3 — Multiple Operations",
    "Handle a set of operations, in sequence.",
    "Since these are verbal word problems, evaluate the expression from left-to-right, _ignoring the typical order of operations._",
    "> What is 5 plus 13 plus 6?",
    "24",
    "> What is 3 plus 2 multiplied by 3?",
    "15 (i.e. not 9)",
    "## Iteration 4 — Errors",
    "The parser should reject:",
    "- Unsupported operations (\"What is 52 cubed?\") - Non-math questions (\"Who is the President of the United States\") - Word problems with invalid syntax (\"What is 1 plus plus 2?\")"
  ],
  "examples": [
    {
      "name": "Wordy > just a number",
      "args": [
        "What is 5?"
      ],
      "expected": 5
    },
    {
      "name": "Wordy > addition",
      "args": [
        "What is 1 plus 1?"
      ],
      "expected": 2
    },
    {
      "name": "Wordy > more addition",
      "args": [
        "What is 53 plus 2?"
      ],
      "expected": 55
    }
  ]
});

// @openarc:begin wordy.answer
export const answer: AnswerFn = (question) => {
  const trimmed = question.trim();
  if (!trimmed.startsWith('What is ')) {
      throw new Error('Invalid question format');
    }
  const expression = trimmed.slice(8).replace('?', '').trim();
  const parts = expression.split(/\s+/);
  if (parts.length === 0) {
      throw new Error('Empty expression');
    }
  let result = parseFloat(parts[0]);
  if (isNaN(result)) {
      throw new Error('Invalid number');
    }
  for (let i = 1; i < parts.length; i += 2) {
      const operator = parts[i];
      const nextValue = parseFloat(parts[i + 1]);
      if (isNaN(nextValue)) {
        throw new Error('Invalid number');
      }
      if (i + 1 >= parts.length) {
        throw new Error('Missing operand');
      }
      switch (operator) {
        case 'plus':
          result += nextValue;
          break;
        case 'minus':
          result -= nextValue;
          break;
        case 'multiplied by':
          result *= nextValue;
          break;
        case 'divided by':
          if (nextValue === 0) {
            throw new Error('Division by zero');
          }
          result /= nextValue;
          break;
        default:
          throw new Error(`Unsupported operation: ${operator}`);
      }
    }
  return Math.round(result);
};
// @openarc:end wordy.answer

export function answer(question: string): number {
  // Remove surrounding whitespace
  const trimmed = question.trim();

  // Expected format: "What is <expression>?"
  if (!trimmed.startsWith("What is ") || !trimmed.endsWith("?")) {
    throw new Error("Unknown operation");
  }

  // Extract the expression part between "What is " and "?"
  const expression = trimmed.slice(8, -1).trim();

  if (!expression) {
    throw new Error("Unknown operation");
  }

  // Tokenize the expression
  // We need to handle numbers (including negatives) and keywords.
  // A simple regex split might break negative numbers if not careful.
  // Strategy: Match numbers (integers) and keywords.

  const keywords = [
    { word: "plus", op: "+" },
    { word: "minus", op: "-" },
    { word: "multiplied", op: "*" },
    { word: "by", op: null }, // "by" is just a connector for multiplication
    { word: "divided", op: "/" },
    { word: "cubed", op: "^3" }, // Special case for iteration 4 errors
    { word: "raised", op: null }, // Often paired with "to"
    { word: "to", op: null }
  ];

  // Let's tokenize manually to handle negative numbers correctly.
  // We scan the string character by character or use a regex that captures numbers and words.

  // Regex to match:
  // 1. Numbers (optional minus sign at start of token, but not in middle of word)
  // 2. Keywords
  // We need to be careful with "minus" vs a negative number like "-5".
  // In the context of "What is 5 minus 5?", "minus" is an operator.
  // In "What is -5?", "-5" is a number.

  // Let's split by spaces first, then process tokens.
  const rawTokens = expression.split(/\s+/);

  // We will build a list of tokens: either a number or an operator keyword.
  // We need to handle the "multiplied by" case which is two words.

  const tokens: (string | number)[] = [];
  let i = 0;

  while (i < rawTokens.length) {
    const token = rawTokens[i];

    // Check for "multiplied by"
    if (token === "multiplied" && i + 1 < rawTokens.length && rawTokens[i + 1] === "by") {
      tokens.push("*");
      i += 2;
      continue;
    }

    // Check for "divided by"
    if (token === "divided" && i + 1 < rawTokens.length && rawTokens[i + 1] === "by") {
      tokens.push("/");
      i += 2;
      continue;
    }

    // Check for "raised to" (though not explicitly requested in examples, usually handled similarly)
    // The prompt doesn't show "raised to", but "cubed" is an error case.
    // Let's stick to the specific operations requested: plus, minus, multiplied, divided.

    // Check for "cubed" or other unsupported operations
    if (["cubed", "raised", "to", "squared", "modulo", "and", "or"].includes(token)) {
      throw new Error("Unknown operation");
    }

    // Check if token is a number
    if (/^-?\d+$/.test(token)) {
      tokens.push(parseInt(token, 10));
    } else {
      // It must be an operator keyword
      const opMap: Record<string, string> = {
        "plus": "+",
        "minus": "-",
        "multiplied": "*", // Handled above, but fallback
        "divided": "/"    // Handled above, but fallback
      };

      if (opMap[token]) {
        tokens.push(opMap[token]);
      } else {
        throw new Error("Unknown operation");
      }
    }
    i++;
  }

  // Now we have a list of tokens: numbers and operators.
  // We need to evaluate left-to-right.

  if (tokens.length === 0) {
    throw new Error("Unknown operation");
  }

  // The first token must be a number
  if (typeof tokens[0] !== 'number') {
    throw new Error("Unknown operation");
  }

  let result = tokens[0];

  for (let j = 1; j < tokens.length; j += 2) {
    const op = tokens[j];
    const nextVal = tokens[j + 1];

    if (typeof nextVal !== 'number') {
      throw new Error("Unknown operation");
    }

    switch (op) {
      case "+":
        result += nextVal;
        break;
      case "-":
        result -= nextVal;
        break;
      case "*":
        result *= nextVal;
        break;
      case "/":
        // Integer division? The examples show 25 / 5 = 5. 
        // Usually word problems imply integer arithmetic or standard division.
        // Given "returning the answer as an integer", let's use standard division 
        // and check if it results in an integer or if we should floor.
        // Example: 25 divided by 5 -> 5.
        // If we have 7 divided by 2, is it 3 or 3.5? 
        // The instructions say "returning the answer as an integer".
        // Let's assume standard division and cast to int if needed, or throw if not divisible?
        // Usually in these exercises (like Codewars Wordy), it expects integer division or exact division.
        // Let's do standard division. If the result is not an integer, we might need to handle it.
        // However, the prompt says "returning the answer as an integer".
        // Let's assume inputs are such that division is exact, or we truncate.
        // Looking at typical "Wordy" kata: it usually expects integer division (floor) or exact.
        // Let's try standard division first.
        result = result / nextVal;
        break;
      default:
        throw new Error("Unknown operation");
    }
  }

  // Ensure the result is an integer (remove floating point errors if any, though inputs are integers)
  // If the division wasn't exact, Math.floor or Math.round?
  // Standard behavior for "integer" return in these contexts is often just casting to int 
  // if the math holds, or throwing if invalid.
  // Let's assume the problem guarantees valid integer results for division or expects truncation.
  // Given "returning the answer as an integer", let's cast to int.

  return Math.round(result);
}

