// @openarc:begin allYourBase.convert
export const convert: ConvertFn = (digits, inputBase, outputBase) => {
  if (inputBase <= 1 || outputBase <= 1) throw new Error('Wrong input/base values');
  if (digits.length === 0) return [];
  if (digits.some(d => d < 0 || d >= inputBase)) throw new Error('Wrong digits');
  let value = 0;
  for (const digit of digits) {
    value = value * inputBase + digit;
  }
  const result: number[] = [];
  while (value > 0) {
    result.unshift(value % outputBase);
    value = Math.floor(value / outputBase);
  }
  return result;
};
// @openarc:end allYourBase.convert

export function convert(
  digits: number[],
  inputBase: number,
  outputBase: number
): number[] {
  // Validate inputBase
  if (inputBase <= 1) {
    throw new Error("Wrong input base");
  }

  // Validate outputBase
  if (outputBase <= 1) {
    throw new Error("Wrong output base");
  }

  // Validate digits array
  if (digits.length === 0) {
    throw new Error("wrong digit count");
  }

  for (const digit of digits) {
    if (digit < 0 || digit >= inputBase) {
      throw new Error("invalid digit for base");
    }
  }

  // Handle the case where the input represents zero (e.g., [0, 0, 0])
  let value = 0;
  for (const digit of digits) {
    value = value * inputBase + digit;
  }

  if (value === 0) {
    return [0];
  }

  // Convert to output base
  const result: number[] = [];
  while (value > 0) {
    result.unshift(value % outputBase);
    value = Math.floor(value / outputBase);
  }

  return result;
}

