// @openarc:begin transpose.transpose
export const transpose: TransposeFn = (rows) => {
  const maxLen = rows.reduce((max, row) => Math.max(max, row.length), 0);
  const result: string[] = [];
  for (let col = 0; col < maxLen; col++) {
    let rowStr = '';
    for (let row = 0; row < rows.length; row++) {
      if (col < rows[row].length) {
        rowStr += rows[row][col];
      } else {
        rowStr += ' ';
      }
    }
    result.push(rowStr);
  }
  return result;
};
// @openarc:end transpose.transpose

export function transpose(rows: string[]): string[] {
  // Handle empty input
  if (rows.length === 0) {
    return [];
  }

  // Determine the maximum length of any row to know how many columns we need
  const maxLen = Math.max(...rows.map((row) => row.length));

  // Initialize the result array with empty strings for each column (which will become rows)
  const result: string[] = new Array(maxLen).fill("");

  // Iterate over each column index
  for (let col = 0; col < maxLen; col++) {
    let newRow = "";

    // Iterate over each row to build the new column
    for (let rowIdx = 0; rowIdx < rows.length; rowIdx++) {
      const currentRow = rows[rowIdx];

      // If the current row has a character at this column index, use it
      if (col < currentRow.length) {
        newRow += currentRow[col];
      } else {
        // If the current row is shorter than the current column index,
        // we need to pad with a space, but only if there are subsequent rows
        // that actually have content at this column index.
        // However, the logic "Don't pad to the right" implies we only add spaces
        // if the column exists in the matrix (i.e., some row has length > col).
        // Since we are iterating col from 0 to maxLen-1, we know the column exists.
        // The rule "Pad to the left with spaces" in the context of different lengths
        // usually means: if a row is shorter, we treat missing chars as spaces.
        // But we must not add trailing spaces to the output row if they aren't needed.
        // Actually, re-reading the requirement: "Pad to the left with spaces" refers to the input matrix logic
        // effectively meaning: when transposing, if a row is short, the missing char is a space.
        // "Don't pad to the right" means the output row shouldn't have trailing spaces if the last row
        // (or any row contributing to the length) ended there? 
        // Let's look at the example:
        // Input:
        // AB
        // DEF
        // Output:
        // AD
        // BE
        //  F
        // Here, row 0 has length 2. Row 1 has length 3.
