    // Max len = 2.
    // Col 0: 'A', 'B' -> "AB"
    // Col 1: ' ', undefined -> " " -> trim -> ""
    // Result: ["AB", ""]
    // Is this correct? "Don't pad to the right" implies we don't output trailing spaces.
    // So yes, trimming seems correct.

    result[col] = newRow.trimEnd();
  }

  return result;
}

