export const decode: DecodeFn = (bytes) => {
  const result: number[] = [];
    let i = 0;
    while (i < bytes.length) {
      let byte = bytes[i];
      let value = byte & 0x7F;
      i++;
      while (byte & 0x80) {
        byte = bytes[i];
        value = (value << 7) | (byte & 0x7F);
        i++;
      }
      result.push(value);
    }
    return result;
};
// @openarc:end variableLengthQuantity.decode

export function encode(numbers: number[]): number[] {
  const result: number[] = [];

  for (const num of numbers) {
    if (num < 0 || num > 0xFFFFFFFF) {
      throw new Error("Number out of range for 32-bit unsigned integer");
    }

    if (num === 0) {
      result.push(0);
      continue;
    }

    let n = num;
    const bytes: number[] = [];

    while (n > 0x7F) {
      bytes.unshift(n & 0x7F);
      n >>= 7;
    }

    bytes.unshift(n & 0x7F);

    for (let i = bytes.length - 1; i >= 0; i--) {
      const byte = bytes[i];
      if (i > 0) {
        result.push(byte | 0x80);
      } else {
        result.push(byte);
      }
    }
  }

  return result;
}

export function decode(bytes: number[]): number[] {
  const result: number[] = [];
  let currentNumber = 0n;
  let shift = 0n;

  for (const byte of bytes) {
    if (typeof byte !== "number" || byte < 0 || byte > 255) {
      throw new Error("Invalid byte value");
    }

    const value = BigInt(byte);
    currentNumber = (currentNumber << 7n) | (value & 0x7Fn);

    if ((byte & 0x80) === 0) {
      // Last byte
      if (currentNumber < 0n || currentNumber > 0xFFFFFFFFn) {
        throw new Error("Decoded number exceeds 32-bit unsigned integer range");
      }
      result.push(Number(currentNumber));
      currentNumber = 0n;
      shift = 0n;
    } else {
      // Not the last byte
      if (shift >= 28n) {
        throw new Error("Too many continuation bytes");
      }
    }
  }

  if (currentNumber !== 0n) {
    throw new Error("Incomplete VLQ sequence");
  }

  return result;
}

